import Cookies from 'js-cookie';
import { Module } from './module/module'; // eslint-disable-next-line import/no-default-export

export default class _class extends Module {
  initialize() {
    if (Cookies.get(this.cookieName) === 'true') return;
    this.element.setAttribute(this.activeAttribute, 'false');
  }

  setupListeners() {
    this.acceptButtonEls.forEach(acceptButton => {
      const acceptBanner = () => {
        Cookies.set(this.cookieName, 'true', {
          expires: 3650
        });
        this.element.setAttribute(this.activeAttribute, 'true');
      };

      this.listeners.add(acceptButton, 'click', acceptBanner);
    });
  }

  get activeAttribute() {
    return 'aria-hidden';
  }

  get cookieName() {
    return 'BAO-cookie-information';
  }

}
_class.targets = ['acceptButton'];